+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private MessageStore store;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    @Test
+    void sendByButtonShowsNotificationAndRowAndClearsForm() {
+        field("Name").fill("Ann");
+        field("Phone").fill("+358 40 1234");
+        field("Message").fill("Hello there");
+        send().click();
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        assertThat(field("Name")).hasValue("");
+        assertThat(field("Message")).hasValue("");
+        assertThat(send()).isDisabled();
+
+        field("Name").fill("Ben");
+        assertThat(send()).isEnabled();
+    }
+
+    @Test
+    void enterInFieldSendsAndValidationErrorsAppearOnEmptySend() {
+        send().click();
+        assertThat(page.getByText("Name is required")).isVisible();
+        assertThat(page.getByText("Message is required")).isVisible();
+
+        field("Name").fill("Cat");
+        field("Email").fill("cat@example.com");
+        field("Message").fill("Via enter");
+        field("Message").press("Enter");
+
+        assertThat(page.getByText("Via enter")).isVisible();
+        assertThat(field("Name")).hasValue("");
+        assertEquals("Cat", store.newestFirst().getFirst().name());
+    }
+
+    @Test
+    void leavingWithInputAsksAndDiscardGoesAhead() {
+        field("Name").fill("Dee");
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+
+        assertThat(page.getByText("Discard your message?")).isVisible();
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).not().isVisible();
+
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).isVisible();
+    }
+
+    private Locator field(String label) {
+        return page.getByLabel(label, new Page.GetByLabelOptions().setExact(true));
+    }
+
+    private Locator send() {
+        return page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send"));
+    }
+
+}
