+        phone().setValue("+358 40 123");
+        message().setValue("Hello");
+        test(sendButton()).click();
+
+        assertEquals(1, store.newestFirst().size());
+        assertEquals("Bo", store.newestFirst().getFirst().name());
+
+        assertTrue($(Notification.class).single().getElement().getProperty("text", "").contains("Message sent"));
+        assertTrue(name().getValue().isEmpty());
+        assertTrue(phone().getValue().isEmpty());
+        assertTrue(message().getValue().isEmpty());
+        assertTrue(email().getValue().isEmpty());
+        assertFalse(sendButton().isEnabled());
+
+        name().setValue("Cy");
+        assertTrue(sendButton().isEnabled());
+    }
+
+    @Test
+    void enterSendsTheMessageAndNewestComesFirst() {
